mod t9_support;

use t9_support::run_with;

// expected values computed by python: two's complement wrapping mod 2^64, shift counts masked to 63
const MODES: [&[&str]; 5] = [
    &["-O0"],
    &["-O2"],
    &["-O3"],
    &["-ae.jit=on"],
    &["-ae.gc-stress=on", "-ae.gc-verify=on"],
];

fn assert_lines(source: &str, expected: &str) {
    let expected: Vec<&str> = expected.lines().collect();
    for flags in MODES {
        let outcome = run_with(source, flags);
        assert_eq!(outcome.code, Some(0), "flags {flags:?}\nstderr: {}", outcome.stderr);
        let got = outcome.lines();
        assert_eq!(got.len(), expected.len(), "flags {flags:?}: line count\n{}", outcome.stdout);
        for (index, (got, want)) in got.iter().zip(&expected).enumerate() {
            let statement = source.lines().nth(index + 2).unwrap_or("");
            assert_eq!(got, want, "flags {flags:?}: line {index}: {statement}");
        }
    }
}

fn assert_refused(source: &str, code: &str) {
    let outcome = run_with(source, &[]);
    assert_ne!(outcome.code, Some(0), "{source}");
    assert!(outcome.stderr.contains(code), "{source}\n{}", outcome.stderr);
}

