#[test]
fn fnv1a_64_matches_the_reference_hash() {
    let mut source = String::from(
        "fn fnv1a(s: string) -> u64 {
    let mut h: u64 = 0xcbf29ce484222325
    for b in s.bytes() {
        h = h ^ (b as u64)
        h = h * 0x100000001b3
    }
    h
}
",
    );
    for text in FNV_STRINGS {
        source.push_str(&format!("let h = fnv1a(\"{text}\")\nprintln(\"{{h}}\")\n"));
    }
    assert_lines(&source, &FNV_EXPECTED.join("\n"));
}

#[test]
fn conversions_between_int_i64_u64_narrow_types_and_float() {
    let source = "fn u(x: u64) -> u64 { x }
fn i(x: i64) -> i64 { x }
fn f(x: float) -> float { x }
let max = u(18446744073709551615)
println(\"{max as int} {max as i64} {max as u8} {max as i32}\")
println(\"{(u(9223372036854775813)) as i32} {(i(-1)) as u64} {(-1) as u64}\")
println(\"{u(9223372036854775808) as i64} {i(-9223372036854775807 - 1) as u64}\")
println(\"{max as float} {u(9223372036854775808) as float}\")
println(\"{f(1.8e19) as u64} {f(-1.5) as u64} {f(1e30) as i64} {f(1e30) as u64}\")
println(\"{(max as int) as u64} {(255 as u8) as u64}\")
";
    assert_lines(
        source,
        "-1 -1 255 -1
5 18446744073709551615 18446744073709551615
-9223372036854775808 9223372036854775808
18446744073709552000.0 9223372036854776000.0
18000000000000000000 18446744073709551615 5076964154930102272 5076964154930102272
18446744073709551615 255",
    );
}

